-- FR WEALTH_NET 2015-01-01..2016-01-01 (back-year) ← pwc-FR-other
update tax_rate set headline_rate = 1.5, rate_min = 0.5, rate_max = 1.5, threshold_amount = 1300000, threshold_note = 'Due only if net wealth on 1 January exceeds €1.3m; the bands then start at €800,000 (a discount applies between €1.3m and €1.4m).', note = 'Wealth tax (ISF, impôt de solidarité sur la fortune) on worldwide net assets, due if net wealth exceeds EUR 1.3 million (2015 tax year), "progressive from 0.50%, after an allowance of EUR 800,000 to 1.5% for net wealth in excess of EUR 10 million" (PwC Other taxes, last reviewed 30 Jan 2015). NOT ONE RATE: 0.5% from €800,000 to €1.3m, 0.7% to €2.57m, 1% to €5m, 1.25% to €10m, 1.5% above €10m (bands: EY Worldwide Personal Tax Guide 2015-16 (content current on 1 July 2015), https://web.archive.org/web/20160327080125/http://www.ey.com:80/Publication/vwLUAssets/Worldwide_Personal_Tax_Guide_2015-16/$FILE/Worldwide%20Personal%20Tax%20Guide%202015-16.pdf). Stored: headline = the top band, threshold = €1.3m; applied to all of the value above €1.3m it overstates the tax below €10m.', source_url = 'https://web.archive.org/web/20150729212138/http://taxsummaries.pwc.com:80/uk/taxsummaries/wwts.nsf/ID/France-Individual-Other-taxes', verified_on = '2015-07-29', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2016-01-01' where jurisdiction_code = 'FR' and tax_type_code = 'WEALTH_NET' and valid_from = '2015-01-01';
